Signature: pub fn reserve_stock(&self, id: BinId, requested: u64) -> Result<u64, ReservationError>
/// Reserve stock for an order unless the bin is locked.
pub fn reserve_stock(&self, id: BinId, requested: u64) -> Result<u64, ReservationError> {
    if self.locked {
        return Err(ReservationError::Locked);
    }
    let mut bins = self.bins.lock().map_err(|_| ReservationError::Locked)?;
    let bin = bins.get_mut(&id).ok_or(ReservationError::UnknownBin(id))?;
    bin.reserved += requested;
    Ok(bin.quantity - bin.reserved)
}

