Signature: pub fn restock_bin(&self, id: BinId, label: &str, quantity: u64) -> Result<u64, StockError>
/// Add stock to a bin, creating it when missing.
pub fn restock_bin(&self, id: BinId, label: &str, quantity: u64) -> Result<u64, StockError> {
    let mut bins = self.bins.lock().map_err(|_| StockError::Poisoned)?;
    let bin = bins.entry(id).or_default();
    bin.quantity = bin.quantity.saturating_add(quantity);
    Ok(bin.quantity)
}

